<script>
const q=s=>document.querySelector(s), qa=s=>document.querySelectorAll(s);qa('.designer-image-nav button').forEach(b=>b.addEventListener('click',()=>{qa('.designer-image-nav button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');qa('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==b.dataset.tab);}));
const ds=q('[name="designer_store"]'),dp=q('[name="designer_prize"]'),dd=q('[name="designer_date"]'),show=q('#designer-show-date'),replacement=q('#designer-date-replacement');ds?.addEventListener('input',()=>qa('.live-store').forEach(e=>e.textContent=ds.value.toUpperCase()));dp?.addEventListener('input',()=>qa('.live-prize').forEach(e=>e.textContent=dp.value));dd?.addEventListener('input',()=>{const d=new Date(dd.value+'T00:00:00');if(!dd.value)return;qa('.live-date').forEach(e=>e.textContent=String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear());});function updateDate(){const box=q('#live-date-box');if(show.checked){box.hidden=false;replacement.disabled=true;}else{box.hidden=false;replacement.disabled=false;box.textContent=replacement.value||'Texto alternativo del sorteo';}}show?.addEventListener('change',updateDate);replacement?.addEventListener('input',updateDate);function selectLogo(){q('#logo-file')?.click()}q('#logo-file')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const url=URL.createObjectURL(f);qa('.fake-logo').forEach(x=>{x.style.background='url('+url+') center/contain no-repeat';x.textContent='';});});q('#designer-ribbon')?.addEventListener('input',e=>qa('[data-live-text="ribbon"]').forEach(x=>x.textContent=e.target.value));q('#designer-thanks')?.addEventListener('input',e=>qa('.client-thanks').forEach(x=>x.textContent=e.target.value));q('#designer-radius')?.addEventListener('change',e=>document.documentElement.style.setProperty('--designer-radius',e.target.value));function resetDesigner(){location.reload()}
const st=q('#image-start'),en=q('#image-end');function syncImageForm(){q('#image-start-hidden').value=st.value;q('#image-quantity-hidden').value=Math.max(1,Number(en.value)-Number(st.value)+1)}[st,en].forEach(e=>e?.addEventListener('input',syncImageForm));function openPreviewModal(){const s=q('.horizontal-ticket'),t=q('#preview-modal-ticket');t.innerHTML='';t.appendChild(s.cloneNode(true));q('#preview-modal').hidden=false}function closePreviewModal(){q('#preview-modal').hidden=true}function printPreview(){window.print()}
</script>
<script>qa('.designer-color-grid button').forEach(b=>b.addEventListener('click',()=>{const c=b.dataset.color;document.documentElement.style.setProperty('--blue',c);qa('.red-ribbon').forEach(x=>x.style.backgroundColor=c);qa('.image-head-btn.green').forEach(x=>x.style.backgroundColor=c);}));q('#save-design')?.addEventListener('click',async()=>{const token=q('input[name="_token"]')?.value;const payload={_token:token,store_name:ds.value,prize:dp.value,draw_date:dd.value,minimum_purchase:'50',accent_color:getComputedStyle(document.documentElement).getPropertyValue('--blue').trim()||'#0877f9',show_draw_date:show.checked?'1':'0',date_replacement:replacement.value};const button=q('#save-design');button.disabled=true;try{const response=await fetch('{{ route('settings.save.ajax') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo guardar');button.textContent='✓ Guardado';setTimeout(()=>button.textContent='▣ Guardar Diseño',1800);}catch(error){button.textContent='Error al guardar';setTimeout(()=>button.textContent='▣ Guardar Diseño',2200);}finally{button.disabled=false;}});</script>
<script>
async function uploadDesignAsset(type,file){if(!file)return;const token=q('input[name="_token"]')?.value;const form=new FormData();form.append('_token',token);form.append('type',type);form.append('image',file);const response=await fetch('{{ route('settings.save.assets') }}',{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':token},body:form});const data=await response.json();if(!response.ok)throw new Error(data.message||'No se pudo subir la imagen');const freshPath=data.path+'?v='+Date.now();if(type==='logo'){qa('.fake-logo').forEach(x=>{x.style.background='url('+freshPath+') center/contain no-repeat';x.textContent='';});qa('.ticket-logo').forEach(x=>{x.classList.add('has-uploaded-logo');let img=x.querySelector('.live-logo');if(!img){img=document.createElement('img');img.className='live-logo';img.alt='Logo';x.prepend(img);}img.src=freshPath;});}else{const box=q('.client-prize');if(box){let img=box.querySelector('.uploaded-prize-image');if(!img){img=document.createElement('img');img.className='uploaded-prize-image';box.prepend(img);}img.src=freshPath;}}}
q('#logo-file')?.addEventListener('change',async e=>{try{await uploadDesignAsset('logo',e.target.files[0]);}catch(error){alert(error.message);}});const prizePicker=document.createElement('input');prizePicker.type='file';prizePicker.accept='image/png,image/jpeg,image/webp';prizePicker.hidden=true;document.body.appendChild(prizePicker);document.querySelectorAll('.designer-image-option')[1]?.addEventListener('click',()=>prizePicker.click());prizePicker.addEventListener('change',async e=>{try{await uploadDesignAsset('prize',e.target.files[0]);}catch(error){alert(error.message);}});
</script>
<script>
updateDate();
q('#designer-font')?.addEventListener('change',e=>qa('.ticket-logo,.ticket-logo b,.client-thanks,.live-store').forEach(x=>x.style.fontFamily=e.target.value));
q('#designer-font-size')?.addEventListener('change',e=>{const size=e.target.value==='large'?'1.18em':e.target.value==='small'?'.86em':'1em';qa('.ticket-logo b,.client-thanks,.live-prize').forEach(x=>x.style.fontSize=size);});
q('#designer-font-color')?.addEventListener('input',e=>qa('.ticket-logo,.ticket-logo b,.client-thanks,.live-store').forEach(x=>x.style.color=e.target.value));
</script>
